DO $g$ DECLARE
  v_stage_count integer;
  v_dup_count integer;
  v_col_count integer;
  v_unmatched integer;
  v_dup_target integer;
BEGIN
  -- Guard 1: stage row count == expected D4 count
  SELECT count(*) INTO v_stage_count FROM stage_029_iccb;
  IF v_stage_count <> 608 THEN
    RAISE EXCEPTION '029 guard [ICCB]: stage row count % != expected 608', v_stage_count;
  END IF;
  -- Guard 2: no duplicate source_id in stage
  SELECT count(*) INTO v_dup_count FROM (
    SELECT source_id FROM stage_029_iccb GROUP BY source_id HAVING count(*) > 1
  ) dups;
  IF v_dup_count > 0 THEN
    RAISE EXCEPTION '029 guard [ICCB]: % duplicate source_id(s) in stage', v_dup_count;
  END IF;
  -- Guard 3: DDL present -- 6 tmt_* columns exist on tcc.brk_iccb_styles
  SELECT count(*) INTO v_col_count FROM information_schema.columns
    WHERE table_schema='tcc' AND table_name='brk_iccb_styles'
      AND column_name IN ('tmt_tcc_number','tmt_notes','tmt_trip_plug',
                          'tmt_breaker_type','tmt_thermal_magnetic','tmt_thermal');
  IF v_col_count <> 6 THEN
    RAISE EXCEPTION '029 guard [ICCB]: DDL missing -- only % of 6 tmt_* columns present on tcc.brk_iccb_styles', v_col_count;
  END IF;
  -- Guard 4: coverage anti-join -- every stage source_id matches exactly one target row
  SELECT count(*) INTO v_unmatched
    FROM stage_029_iccb st
    LEFT JOIN tcc.brk_iccb_styles t ON t.source_id = st.source_id
    WHERE t.source_id IS NULL;
  IF v_unmatched > 0 THEN
    RAISE EXCEPTION '029 guard [ICCB]: % stage source_id(s) have no match in tcc.brk_iccb_styles (orphan rows)', v_unmatched;
  END IF;
  -- Guard 4b: source_id is unique in the target (no fan-out)
  SELECT count(*) INTO v_dup_target FROM (
    SELECT source_id FROM tcc.brk_iccb_styles GROUP BY source_id HAVING count(*) > 1
  ) dup_t;
  IF v_dup_target > 0 THEN
    RAISE EXCEPTION '029 guard [ICCB]: % non-unique source_id(s) in tcc.brk_iccb_styles -- UPDATE would fan-out', v_dup_target;
  END IF;
END $g$;
UPDATE tcc.brk_iccb_styles s
  SET tmt_tcc_number       = st.tmt_tcc_number,
      tmt_notes            = st.tmt_notes,
      tmt_trip_plug        = st.tmt_trip_plug,
      tmt_breaker_type     = st.tmt_breaker_type,
      tmt_thermal_magnetic = st.tmt_thermal_magnetic,
      tmt_thermal          = st.tmt_thermal
  FROM stage_029_iccb st
  WHERE s.source_id = st.source_id;
DO $pw$ DECLARE v_updated integer; v_expected integer;
BEGIN
  SELECT count(*) INTO v_expected FROM stage_029_iccb;
  SELECT count(*) INTO v_updated
    FROM stage_029_iccb st
    JOIN tcc.brk_iccb_styles t ON t.source_id = st.source_id
    WHERE t.tmt_tcc_number IS NOT DISTINCT FROM st.tmt_tcc_number
      AND t.tmt_notes IS NOT DISTINCT FROM st.tmt_notes
      AND t.tmt_trip_plug IS NOT DISTINCT FROM st.tmt_trip_plug
      AND t.tmt_breaker_type IS NOT DISTINCT FROM st.tmt_breaker_type
      AND t.tmt_thermal_magnetic IS NOT DISTINCT FROM st.tmt_thermal_magnetic
      AND t.tmt_thermal IS NOT DISTINCT FROM st.tmt_thermal;
  IF v_updated <> v_expected THEN
    RAISE EXCEPTION '029 post-write [ICCB]: only % of % rows updated (values landed)', v_updated, v_expected;
  END IF;
END $pw$;
CREATE TEMP TABLE stage_029_mccb (source_id integer, tmt_tcc_number text, tmt_notes text, tmt_trip_plug smallint, tmt_breaker_type smallint, tmt_thermal_magnetic smallint, tmt_thermal smallint) ON COMMIT DROP;
