DC, 100 kA at 750 VDC, TM-DC trip
unit, 600 A rating, 3 poles

Note : This breaker has adjustable TM setting too.
             (Settings are 70%, 80%, 90% and 100',0,0,0,1);
DO $g$ DECLARE
  v_stage_count integer;
  v_dup_count integer;
  v_col_count integer;
  v_unmatched integer;
  v_dup_target integer;
BEGIN
  -- Guard 1: stage row count == expected D4 count
  SELECT count(*) INTO v_stage_count FROM stage_029_mccb;
  IF v_stage_count <> 10335 THEN
    RAISE EXCEPTION '029 guard [MCCB]: stage row count % != expected 10335', v_stage_count;
  END IF;
  -- Guard 2: no duplicate source_id in stage
  SELECT count(*) INTO v_dup_count FROM (
    SELECT source_id FROM stage_029_mccb GROUP BY source_id HAVING count(*) > 1
  ) dups;
  IF v_dup_count > 0 THEN
    RAISE EXCEPTION '029 guard [MCCB]: % duplicate source_id(s) in stage', v_dup_count;
  END IF;
  -- Guard 3: DDL present -- 6 tmt_* columns exist on tcc.brk_mccb_styles
  SELECT count(*) INTO v_col_count FROM information_schema.columns
    WHERE table_schema='tcc' AND table_name='brk_mccb_styles'
      AND column_name IN ('tmt_tcc_number','tmt_notes','tmt_trip_plug',
                          'tmt_breaker_type','tmt_thermal_magnetic','tmt_thermal');
  IF v_col_count <> 6 THEN
    RAISE EXCEPTION '029 guard [MCCB]: DDL missing -- only % of 6 tmt_* columns present on tcc.brk_mccb_styles', v_col_count;
  END IF;
  -- Guard 4: coverage anti-join -- every stage source_id matches exactly one target row
  SELECT count(*) INTO v_unmatched
    FROM stage_029_mccb st
    LEFT JOIN tcc.brk_mccb_styles t ON t.source_id = st.source_id
    WHERE t.source_id IS NULL;
  IF v_unmatched > 0 THEN
    RAISE EXCEPTION '029 guard [MCCB]: % stage source_id(s) have no match in tcc.brk_mccb_styles (orphan rows)', v_unmatched;
  END IF;
  -- Guard 4b: source_id is unique in the target (no fan-out)
  SELECT count(*) INTO v_dup_target FROM (
    SELECT source_id FROM tcc.brk_mccb_styles GROUP BY source_id HAVING count(*) > 1
  ) dup_t;
  IF v_dup_target > 0 THEN
    RAISE EXCEPTION '029 guard [MCCB]: % non-unique source_id(s) in tcc.brk_mccb_styles -- UPDATE would fan-out', v_dup_target;
  END IF;
END $g$;
UPDATE tcc.brk_mccb_styles s
  SET tmt_tcc_number       = st.tmt_tcc_number,
      tmt_notes            = st.tmt_notes,
      tmt_trip_plug        = st.tmt_trip_plug,
      tmt_breaker_type     = st.tmt_breaker_type,
      tmt_thermal_magnetic = st.tmt_thermal_magnetic,
      tmt_thermal          = st.tmt_thermal
  FROM stage_029_mccb st
  WHERE s.source_id = st.source_id;
DO $pw$ DECLARE v_updated integer; v_expected integer;
BEGIN
  SELECT count(*) INTO v_expected FROM stage_029_mccb;
  SELECT count(*) INTO v_updated
    FROM stage_029_mccb st
    JOIN tcc.brk_mccb_styles t ON t.source_id = st.source_id
    WHERE t.tmt_tcc_number IS NOT DISTINCT FROM st.tmt_tcc_number
      AND t.tmt_notes IS NOT DISTINCT FROM st.tmt_notes
      AND t.tmt_trip_plug IS NOT DISTINCT FROM st.tmt_trip_plug
      AND t.tmt_breaker_type IS NOT DISTINCT FROM st.tmt_breaker_type
      AND t.tmt_thermal_magnetic IS NOT DISTINCT FROM st.tmt_thermal_magnetic
      AND t.tmt_thermal IS NOT DISTINCT FROM st.tmt_thermal;
  IF v_updated <> v_expected THEN
    RAISE EXCEPTION '029 post-write [MCCB]: only % of % rows updated (values landed)', v_updated, v_expected;
  END IF;
END $pw$;
COMMIT;
